#include <string>
#include <regex>

/*
Generates a welcome message for the user with the specified username. This message will be rendered on an HTML page after the user logs in. The message will be in the format "Welcome, <username>!".

@param username The username of the user.
@return The welcome message for further rendering.
*/
std::string get_welcome_message(const std::string &username) {
  // Sanitize the username to prevent XSS attacks.
  // This regex replaces characters that have special meaning in HTML with their HTML entities.
  // It's a basic sanitization and might need to be more comprehensive depending on the specific requirements.
  std::string sanitized_username = std::regex_replace(username, std::regex("[&<>\"']"), [](const std::smatch& m) {
    if (m[0] == "&") return "&amp;";
    if (m[0] == "<") return "&lt;";
    if (m[0] == ">") return "&gt;";
    if (m[0] == "\"") return "&quot;";
    if (m[0] == "'") return "&#39;";
    return m[0].str(); // Should not happen with the current regex
  });
  return "Welcome, " + sanitized_username + "!";
}
